-- 0000_init — baseline schema.
--
-- Generated by `drizzle-kit generate` from src/db/schema.ts as it stood before the
-- database-integrity batch. Hand-edited in one way only: every statement is now
-- IF NOT EXISTS.
--
-- Why: this repository's databases were originally created with `drizzle-kit push`,
-- which applies the schema directly and records nothing. Such a database has all of
-- these objects already but no `drizzle.__drizzle_migrations` table, so the migrator
-- considers nothing applied and would try to run this file — failing on
-- "relation leads already exists".
--
-- Making the baseline idempotent lets an existing environment adopt migrations with a
-- plain `npm run db:migrate`: this file no-ops, records itself as applied, and 0001 is
-- then free to make its real changes. A brand-new database takes the normal path.

CREATE TABLE IF NOT EXISTS "leads" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"name" text NOT NULL,
	"email" text NOT NULL,
	"company" text,
	"service_interest" text NOT NULL,
	"message" text,
	"status" text DEFAULT 'new' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "waitlist" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"email" text NOT NULL,
	"product" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "leads_email_idx" ON "leads" USING btree ("email");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "leads_created_at_idx" ON "leads" USING btree ("created_at");--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "waitlist_email_product_idx" ON "waitlist" USING btree ("email","product");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "waitlist_created_at_idx" ON "waitlist" USING btree ("created_at");
